package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/planning/projects/{projectId}/members") public class PlanningProjectMemberController {private final PlanningProjectMemberService service;public PlanningProjectMemberController(PlanningProjectMemberService s){service=s;} @PostMapping public Mono<PlanningProjectMemberView> add(@RequestHeader("X-Ikaros-Actor-Id")UUID owner,@PathVariable UUID projectId,@Valid@RequestBody AddPlanningProjectMemberRequest r){return service.add(owner,projectId,r);}@GetMapping public Flux<PlanningProjectMemberView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID owner,@PathVariable UUID projectId){return service.list(owner,projectId);}@DeleteMapping("/{userId}")public Mono<Void> remove(@RequestHeader("X-Ikaros-Actor-Id")UUID owner,@PathVariable UUID projectId,@PathVariable UUID userId){return service.remove(owner,projectId,userId);}}
